// Generated by vibelang from src/session/message-id-from-hash.ts; the migrate flow writes it again with each batch.
export const messageIdFromHash = (hash) => {
    const value = hash.startsWith("#") ? hash.slice(1) : hash;
    const match = value.match(/^message-(.+)$/);
    if (!match)
        return;
    return match[1];
};
